def solve(grid):
    # Find all 2x2 blocks of 2's
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    blocks = []
    for i in range(rows - 1):
        for j in range(cols - 1):
            if (grid[i][j] == 2 and grid[i][j + 1] == 2 and
                grid[i + 1][j] == 2 and grid[i + 1][j + 1] == 2):
                blocks.append((i, j))

    # If no blocks, return empty 3x3 grid
    if not blocks:
        return [[0, 0, 0],
                [0, 0, 0],
                [0, 0, 0]]

    # ---------- Row mapping ----------
    distinct_rows = sorted({i for i, _ in blocks})
    row_map = {}
    k_rows = len(distinct_rows)
    if k_rows <= 2:
        for r in distinct_rows:
            row_map[r] = 0
    else:
        for pos, r in enumerate(distinct_rows):
            if pos < 2:
                row_map[r] = 0
            elif pos == 2:
                row_map[r] = 1
            else:
                row_map[r] = 2

    # Group blocks by their output row (keeping original order)
    blocks.sort(key=lambda x: (x[0], x[1]))
    rows_dict = {}
    for i, j in blocks:
        out_row = row_map[i]
        rows_dict.setdefault(out_row, []).append(j)

    # ---------- Column mapping for each output row ----------
    col_map_per_row = {}
    for r, col_list in rows_dict.items():
        distinct_cols = sorted(set(col_list))
        k = len(distinct_cols)
        mapping = {}
        if k == 0:
            pass
        elif k == 1:
            # single column: put it in the middle column for the middle row,
            # otherwise in the leftmost column.
            if r == 1:
                mapping[distinct_cols[0]] = 1
            else:
                mapping[distinct_cols[0]] = 0
        else:
            base = k // 3
            rem = k % 3
            left_cap = base + (1 if rem == 2 else 0)
            mid_cap = base + (1 if rem == 1 else 0)
            right_cap = base + (1 if rem == 2 else 0)
            for idx, col in enumerate(distinct_cols):
                if idx < left_cap:
                    out_c = 0
                elif idx < left_cap + mid_cap:
                    out_c = 1
                else:
                    out_c = 2
                mapping[col] = out_c
        col_map_per_row[r] = mapping

    # ---------- Place the 1's ----------
    out_grid = [[0, 0, 0] for _ in range(3)]
    from collections import defaultdict
    col_counter = defaultdict(lambda: defaultdict(int))

    for i, j in blocks:
        r_out = row_map[i]
        base_col = col_map_per_row[r_out].get(j, 0)
        shift = col_counter[r_out][j]
        final_col = base_col - shift
        if final_col < 0:
            final_col = 0
        out_grid[r_out][final_col] = 1
        col_counter[r_out][j] += 1

    return out_grid

